-- =====================================================================
-- 20261029110000_admin_test_assets.sql   (GENERATED by gen_test_assets.cjs; see PORT_PROGRESS)
--
-- Purpose
--   Series banners and question figures, stored in Supabase Storage.
--   Before this file nothing could store them:
--     * no RPC ever wrote test_series_admin.cover_path (the column was only read);
--     * question images were base64 data URLs kept in browser state and sent
--       as-is into quiz_question_admin.image_path (never uploaded, never shown
--       to students).
--
--   1. The public bucket 'test-assets' (images only, 3 MB). No policies on
--      storage.objects: uploads go through signed upload URLs that the
--      asset-upload-url Edge Function creates with the service role, and a
--      public bucket is readable without policies.
--   2. Stored values are bucket-relative paths:
--        '<uploader uid>/banner/<uuid>.<jpg|png|webp>'          (cover_path)
--        '<uploader uid>/question_image/<uuid>.<jpg|png|webp>'  (image_path)
--      adm_test_asset_path(value, kind, keep) is the one check, used by every
--      writer below. Rules:
--        * '' or null removes the image (null);
--        * an optional leading 'test-assets/' is dropped;
--        * data: / blob: URLs (the old browser-only values) are refused;
--        * '..' is refused; the path must match the shape above exactly, for
--          the right kind;
--        * the first segment must be the caller's uid, unless the caller is
--          an admin, or the path is already stored on the row / series being
--          edited (keep), so an assigned educator can keep an admin's image
--          and duplicates keep their paths.
--   3. quiz_question_admin.image_alt (new nullable column, our table): alt
--      text for the figure.
--   4. Reads: get_test_series / list_test_series (already return cover_path
--      through adm_series_rows), adm_question_json (+ image_alt),
--      student_get_test_intro (+ series_cover_path), student_start_attempt
--      (+ image_alt, series_cover_path), student_get_report and
--      student_submit_attempt (stored reports are enriched at read time with
--      image_path / image_alt per question and series_cover_path;
--      adm_report_with_images). No student RPC returns more answer data
--      than before.
--   5. adm_claim_asset_upload_slot(kind, limit): the Edge Function's
--      caller check (admin or verified educator, adm_actor_kind) and rate
--      limit (rolling hour, default 60).
--
-- Replaced (marked "-- 20261029110000"; the rest of each body is verbatim
-- from the file named above it):
--   adm_question_json, adm_insert_question, adm_insert_questions_bulk,
--   adm_copy_quiz, create_test_series, update_test_series,
--   duplicate_test_series, upsert_test_series_full, update_question,
--   list_pending_series_approvals (+ cover_path), student_get_test_intro, student_start_attempt, student_submit_attempt,
--   student_get_report.
--
-- Our objects (new): bucket test-assets, table test_asset_upload_requests
--   (user_id -> profiles ON DELETE CASCADE, indexed; RLS on, no policies,
--   no grants), column quiz_question_admin.image_alt, functions
--   adm_test_asset_path, adm_report_with_images, adm_claim_asset_upload_slot.
--   No lead table, trigger, RLS or policy is touched.
--
-- ROLLBACK
--   scripts/rollback_20261029110000_admin_test_assets.sql
-- =====================================================================
set search_path = public, extensions;

-- --------------------------------------------------------------- preflight
do $pre$
declare
  v_problems text[] := '{}';
  v_sig      text;
  v_type     text;
begin
