    'public.adm_question_json(uuid)', 'public.adm_insert_question(uuid,integer,jsonb,uuid,text)',
    'public.adm_insert_questions_bulk(uuid,jsonb,text)', 'public.adm_copy_quiz(uuid,uuid,integer,text)',
    'public.create_test_series(jsonb)', 'public.update_test_series(uuid,jsonb)', 'public.duplicate_test_series(uuid)',
    'public.upsert_test_series_full(jsonb,boolean)', 'public.update_question(uuid,jsonb)',
    'public.list_pending_series_approvals(text,integer,integer)',
    'public.student_get_test_intro(uuid)', 'public.student_start_attempt(uuid)',
    'public.student_submit_attempt(uuid)', 'public.student_get_report(uuid)',
    'public.adm_actor_kind()', 'public.adm_is_platform_admin()', 'public.adm_series_rows()']
  loop
    if to_regprocedure(v_sig) is null then
      v_problems := v_problems || format('missing %s (apply the earlier migrations first)', v_sig);
    end if;
  end loop;
  foreach v_sig in array array['adm_test_asset_path', 'adm_report_with_images', 'adm_claim_asset_upload_slot'] loop
    if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                where n.nspname = 'public' and p.proname = v_sig) then
      v_problems := v_problems || format('function public.%s already exists', v_sig);
    end if;
  end loop;
  if to_regclass('public.test_asset_upload_requests') is not null then
    v_problems := v_problems || 'table public.test_asset_upload_requests already exists'::text;
  end if;
  if to_regclass('public.test_series_admin') is null or to_regclass('public.quiz_question_admin') is null then
    v_problems := v_problems || 'missing test_series_admin / quiz_question_admin (apply 20261025110100 first)'::text;
  end if;
  select format_type(a.atttypid, a.atttypmod) into v_type
    from pg_attribute a
   where a.attrelid = to_regclass('public.quiz_question_admin') and a.attname = 'image_alt' and not a.attisdropped;
  if v_type is not null and v_type <> 'text' then
    v_problems := v_problems || format('quiz_question_admin.image_alt exists with type %s', v_type);
  end if;
  if to_regclass('storage.buckets') is null then
    v_problems := v_problems || 'missing storage.buckets'::text;
  elsif exists (select 1 from storage.buckets b where b.id = 'test-assets' and not coalesce(b.public, false)) then
    v_problems := v_problems || 'bucket test-assets exists and is private (banners and figures are served by public URL)'::text;
  end if;
  if cardinality(v_problems) > 0 then
    raise exception 'Test assets preflight: %', array_to_string(v_problems, '; ');
  end if;
