-- ------------------------------------------------------------ our objects
alter table public.quiz_question_admin add column if not exists image_alt text;

create table if not exists public.test_asset_upload_requests (
  id          bigserial primary key,
  user_id     uuid not null references public.profiles(id) on delete cascade,
  kind        text,
