-- smoke checks
do $chk$
begin
  if not exists (select 1 from storage.buckets where id = 'test-assets' and public) then
    raise exception 'trial: bucket test-assets missing or private';
  end if;
  if public.adm_test_asset_path('', 'banner') is not null then
    raise exception 'trial: empty path should remove the image';
  end if;
  begin
    perform public.adm_test_asset_path('../x.png', 'banner');
    raise exception 'trial: ".." accepted';
  exception when sqlstate '22023' then null;
  end;
  if public.adm_test_asset_path('test-assets/0f8fad5b-d9cb-469f-a165-70867728950e/banner/7c9e6679-7425-40de-944b-e07fc1f90ae7.webp',
                                'banner', array['0f8fad5b-d9cb-469f-a165-70867728950e/banner/7c9e6679-7425-40de-944b-e07fc1f90ae7.webp'])
     <> '0f8fad5b-d9cb-469f-a165-70867728950e/banner/7c9e6679-7425-40de-944b-e07fc1f90ae7.webp' then
    raise exception 'trial: kept path not normalized';
  end if;
  if not exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'quiz_question_admin' and column_name = 'image_alt') then
    raise exception 'trial: image_alt missing';
  end if;
end $chk$;

rollback;
